# PnL Card Generator
# Final plain 1536x1024 PnL template. The artwork is fixed; only dynamic
# token data is drawn on top of the intentionally empty fields.
PNL_TEMPLATE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "apearadarx_pnl_template.png")

# The PnL artwork is embedded so the bot can be deployed to Render as a single
# Python file. It is extracted automatically on startup.
_PNL_TEMPLATE_B64 = """"""

def ensure_pnl_template():
    if os.path.exists(PNL_TEMPLATE_PATH):
        return
    with open(PNL_TEMPLATE_PATH, "wb") as f:
        f.write(base64.b64decode(_PNL_TEMPLATE_B64))


def format_mcap(n):
    try:
        n = float(n)
        if n >= 1_000_000_000: return f"${n/1_000_000_000:.1f}B"
        if n >= 1_000_000: return f"${n/1_000_000:.1f}M"
        if n >= 1_000: return f"${n/1_000:.1f}K"
        return f"${n:.0f}"
    except: return "N/A"


def get_font(size):
    for p in [
        "/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed-Bold.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
    ]:
        try: return ImageFont.truetype(p, size)
        except: continue
    return ImageFont.load_default()


def fit_font(text, max_width, start_size, min_size=16):
    for size in range(start_size, min_size - 1, -2):
        f = get_font(size)
        b = f.getbbox(text)
        if b[2] - b[0] <= max_width:
            return f
    return get_font(min_size)


def center_text(draw, box, text, font, fill, stroke_width=0, stroke_fill=None):
    x1, y1, x2, y2 = box
    b = draw.textbbox((0, 0), text, font=font, stroke_width=stroke_width)
    tw, th = b[2] - b[0], b[3] - b[1]
    x = x1 + (x2 - x1 - tw) / 2
    y = y1 + (y2 - y1 - th) / 2 - b[1]
    draw.text((x, y), text, font=font, fill=fill,
              stroke_width=stroke_width, stroke_fill=stroke_fill)


def _download_logo(url):
    if not url:
        return None
    try:
        r = requests.get(url, timeout=8)
        r.raise_for_status()
        return Image.open(io.BytesIO(r.content)).convert("RGBA")
    except:
        return None


def _draw_logo(img, logo_url):
    # Remove the sample coin completely, then recreate the gold ring and place
    # the live token logo inside it. This prevents the old token name/artwork
    # from remaining around the new logo.
    cx, cy = 768, 161
    outer_r, inner_r = 112, 84
    layer = Image.new("RGBA", img.size, (0, 0, 0, 0))
    d = ImageDraw.Draw(layer, "RGBA")
    d.ellipse((cx-outer_r, cy-outer_r, cx+outer_r, cy+outer_r), fill=(3, 7, 2, 255), outline=(185, 205, 55, 255), width=5)
    d.ellipse((cx-inner_r, cy-inner_r, cx+inner_r, cy+inner_r), fill=(8, 15, 5, 255), outline=(225, 190, 45, 255), width=3)
    glow = layer.filter(ImageFilter.GaussianBlur(8))
    img = Image.alpha_composite(img, glow)
    img = Image.alpha_composite(img, layer)
    logo = _download_logo(logo_url)
    if logo is not None:
        logo.thumbnail((inner_r*2-10, inner_r*2-10), Image.LANCZOS)
        mask = Image.new("L", logo.size, 0)
        ImageDraw.Draw(mask).ellipse((0, 0, logo.width-1, logo.height-1), fill=255)
        logo.putalpha(mask)
        img.alpha_composite(logo, (cx-logo.width//2, cy-logo.height//2))
    return img


def generate_pnl_card(token_name, token_symbol, buy_mcap, current_mcap,
                     username, invested_sol, token_logo_url=None):
    """Generate the new ApeRadarX PnL card from the supplied artwork.

    Data sources:
      - token name/symbol/logo/current market cap: token CA
      - entry market cap: user input
      - invested SOL: user input
      - PnL %, profit SOL and position SOL: calculated
      - called by: Telegram username
    """
    ensure_pnl_template()
    if not os.path.exists(PNL_TEMPLATE_PATH):
        raise FileNotFoundError("ApeRadarX PnL template is missing.")

    img = Image.open(PNL_TEMPLATE_PATH).convert("RGBA")
    if img.size != (1536, 1024):
        img = img.resize((1536, 1024), Image.LANCZOS)

    green = (165, 255, 35, 255)
    white = (255, 255, 255, 255)
    dark = (0, 15, 3, 255)

    buy_mcap = float(buy_mcap)
    current_mcap = float(current_mcap)
    invested_sol = float(invested_sol)

    multiplier = current_mcap / buy_mcap if buy_mcap > 0 else 0.0
    pnl_percent = (multiplier - 1.0) * 100.0
    profit_sol = invested_sol * (multiplier - 1.0)
    position_sol = invested_sol * multiplier

    # Cover only the sample dynamic values while preserving the original artwork.
    patch = Image.new("RGBA", img.size, (0, 0, 0, 0))
    pd = ImageDraw.Draw(patch, "RGBA")

    # Token/logo circle.
    cx, cy = 220, 514
    outer_r, inner_r = 73, 56
    pd.ellipse((cx-outer_r, cy-outer_r, cx+outer_r, cy+outer_r),
               fill=(0, 10, 2, 255), outline=(165, 255, 35, 255), width=4)
    pd.ellipse((cx-inner_r, cy-inner_r, cx+inner_r, cy+inner_r),
               fill=(5, 15, 5, 255), outline=(165, 255, 35, 255), width=2)

    # Existing sample dynamic text.
    pd.rounded_rectangle((280, 430, 990, 600), radius=18, fill=dark)
    pd.rectangle((1070, 360, 1390, 425), fill=dark)
    pd.rectangle((1070, 485, 1390, 545), fill=dark)
    pd.rectangle((1070, 610, 1390, 675), fill=dark)
    pd.rounded_rectangle((300, 765, 790, 835), radius=8, fill=dark)
    pd.rounded_rectangle((900, 765, 1285, 835), radius=8, fill=dark)

    # Add a clean token-name line beneath PROFIT.
    pd.rounded_rectangle((285, 408, 700, 447), radius=8, fill=dark)

    img = Image.alpha_composite(img, patch)
    draw = ImageDraw.Draw(img, "RGBA")

    # Live token name/symbol.
    name = re.sub(r"\s+", " ", str(token_name or token_symbol or "TOKEN").strip())
    symbol = str(token_symbol or "TOKEN").upper().strip()
    if len(name) > 28:
        name = name[:27].rstrip() + "…"
    if len(symbol) > 12:
        symbol = symbol[:12]

    center_text(draw, (285, 405, 700, 447), name,
                fit_font(name, 390, 31, 18), white)

    # Live token logo.
    logo = _download_logo(token_logo_url)
    if logo is not None:
        logo.thumbnail((inner_r * 2 - 8, inner_r * 2 - 8), Image.LANCZOS)
        mask = Image.new("L", logo.size, 0)
        ImageDraw.Draw(mask).ellipse((0, 0, logo.width-1, logo.height-1), fill=255)
        logo.putalpha(mask)
        img.alpha_composite(logo, (cx - logo.width // 2, cy - logo.height // 2))

    # Profit in SOL.
    profit_text = f"{profit_sol:+,.2f} SOL"
    center_text(draw, (280, 440, 990, 600), profit_text,
                fit_font(profit_text, 690, 128, 64), green,
                stroke_width=3, stroke_fill=(220, 255, 80, 255))

    # PnL percentage.
    pnl_text = f"{pnl_percent:+,.2f}%"
    center_text(draw, (1070, 355, 1390, 425), pnl_text,
                fit_font(pnl_text, 290, 48, 26), white)

    # Invested and position in SOL.
    invested_text = f"{invested_sol:,.2f} SOL"
    position_text = f"{position_sol:,.2f} SOL"

    center_text(draw, (1070, 480, 1390, 545), invested_text,
                fit_font(invested_text, 285, 42, 22), white)

    center_text(draw, (1070, 605, 1390, 675), position_text,
                fit_font(position_text, 285, 42, 22), white)

    # Caller.
    caller = f"@{username}" if username else "@ApeRadarX"
    center_text(draw, (300, 760, 790, 835), caller,
                fit_font(caller, 455, 44, 24), white)

    # Current market cap from the pasted CA.
    current_text = format_mcap(current_mcap)
    center_text(draw, (900, 760, 1285, 835), current_text,
                fit_font(current_text, 355, 48, 26), white)

    out = io.BytesIO()
    img.convert("RGB").save(out, format="PNG")
    out.seek(0)
    return out

